var C = ARISTO.colors;
var scoreIn = document.getElementById('score');
var scoreVal = document.getElementById('scoreVal');
var readout = document.getElementById('readout');

var branches = [
  { code: 'if score >= 90:', label: 'if score >= 90', result: '"A"', test: function (s) { return s >= 90; } },
  { code: 'elif score >= 70:', label: 'elif score >= 70', result: '"B"', test: function (s) { return s >= 70; } },
  { code: 'elif score >= 50:', label: 'elif score >= 50', result: '"C"', test: function (s) { return s >= 50; } },
  { code: 'else:', label: 'else', result: '"F"', test: function () { return true; } }
];

function evaluate(score) {
  var states = []; // 'skipped' (not reached), 'checked-false', 'checked-true-run'
  var decided = false;
  for (var i = 0; i < branches.length; i++) {
    if (decided) {
      states.push('notreached');
      continue;
    }
    var isTrue = branches[i].test(score);
    if (isTrue) {
      states.push('run');
      decided = true;
    } else {
      states.push('checked-false');
    }
  }
  return states;
}

var plot = ARISTO.canvas(document.getElementById('flow'), function (ctx, w, h) {
  var score = +scoreIn.value;
  var states = evaluate(score);
  var n = branches.length;
  var gap = 8;
  var boxH = (h - gap * (n - 1) - 8) / n;
  var boxW = w - 16;
  var x = 8;
  var y = 4;

  ctx.textBaseline = 'middle';
  ctx.font = '600 13px system-ui, sans-serif';

  for (var i = 0; i < n; i++) {
    var st = states[i];
    var fill, strokeCol, textCol;
    if (st === 'run') {
      fill = C.warning; strokeCol = C.warning; textCol = C.ink;
    } else if (st === 'checked-false') {
      fill = C.success; strokeCol = C.success; textCol = C.accentInk;
    } else {
      fill = C.surface; strokeCol = C.line; textCol = C.muted;
    }

    ctx.fillStyle = fill;
    ctx.strokeStyle = strokeCol;
    ctx.lineWidth = st === 'run' ? 3 : 1.5;
    roundRect(ctx, x, y, boxW, boxH, 8);
    ctx.fill();
    ctx.stroke();

    var cx = x + 10;
    var cy = y + boxH / 2;
    ctx.fillStyle = textCol;
    ctx.font = '600 13px ui-monospace, Menlo, Consolas, monospace';
    ctx.fillText(branches[i].code, cx, cy - 8);

    ctx.font = '500 12px system-ui, sans-serif';
    var note;
    if (st === 'run') note = 'runs -> grade = ' + branches[i].result;
    else if (st === 'checked-false') note = 'false, skip';
    else note = 'not reached';
    ctx.fillText(note, cx, cy + 10);

    // arrow to next box
    if (i < n - 1) {
      var ax = x + boxW / 2;
      var ay1 = y + boxH;
      var ay2 = ay1 + gap;
      ctx.strokeStyle = C.muted;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(ax, ay1);
      ctx.lineTo(ax, ay2);
      ctx.stroke();
    }

    y += boxH + gap;
  }
}, 0.62);

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function update() {
  var score = +scoreIn.value;
  scoreVal.textContent = String(score);
  var states = evaluate(score);
  var runIdx = states.indexOf('run');
  var grade = branches[runIdx].result;
  var labelMap = ['first condition', 'second condition', 'third condition', 'else branch'];
  readout.textContent = 'Score = ' + score + ' \u2192 the ' + labelMap[runIdx] + ' runs, grade = ' + grade;
  plot.redraw();
}

scoreIn.addEventListener('input', update);
update();
